UPDATE lessons SET title='Year 4, Week 15, Lesson 2: Unit review and showcase', data=json_patch(data,'{"child_mission":"Unit review connects food groups, labels, lunchboxes, advertising and food safety with respectful language.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same idea to a new game or situation, then compare two choices for safety and inclusion.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nMini: per 100 g why; one safety rule.\n\nFEEDBACK\nFair compare; wash hands / adult for heat.\n\nWATCH FOR\nReview that shames food choices fails the unit aim.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nFourteen-item food review + showcase: label compare and kind lunchbox plan. Two goals.\n\nWrite a short reflection naming one choice you changed and why. Any movement is optional, adult-supervised and can be done in a gentler way or described instead.","interactive_activities":null,"learning_area":"PDHPE","learning_intention":"Unit review connects food groups, labels, lunchboxes, advertising and food safety with respectful language.","lesson_number":2,"lesson_role":"Practise and apply","materials":["Paper or typed answer space","Pencil","Clear, safe movement space with an adult nearby for any physical activity","Optional: soft ball, cushion or water bottle"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["PH2-IHW-01"],"parent_notes":"Parent: Marking guidance for the independent task: Fourteen-item food review + showcase: label compare and kind lunchbox plan. Two goals. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original response on new material: Fair compare; wash hands / adult for heat. Reasoning: I used review by attending to food rather than copying the worked model.\n\nParent: Written model 2: Common error: Review that shames food choices fails the unit aim. Correction: Fair compare; wash hands / adult for heat. Why: the correction restores accurate use of review.\n\nParent: Likely misconception: Review that shames food choices fails the unit aim. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Produce a fresh example demonstrating review on new material (not the worked model). Explain the particular words, sources or choices that make it work.\n\nParent: Short-answer focus 2: Name one likely error with review, correct it, and explain why the correction helps a reader or audience.\n\nParent: Marking notes: Require independently produced work with a specific supporting detail. / Require misconception + correction + purpose-linked reason..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":1,"explanation":"Fair compare; wash hands / adult for heat. This matches the lesson skill for review.","options":["Copy the example and call that independent work.","Fair compare; wash hands / adult for heat.","Review that shames food choices fails the unit aim.","Ignore the safety rule because the first idea looked exciting."],"question":"Mini: per 100 g why; one safety rule. Which response is most accurate?","type":"multiple_choice"},{"correct_index":3,"explanation":"Review that shames food choices fails the unit aim. That misconception weakens accuracy; the other choices align with the lesson idea.","options":["Unit review connects food groups, labels, lunchboxes, advertising and food safety with respectful language.","Fair compare; wash hands / adult for heat.","Careful use of food with clear evidence.","Review that shames food choices fails the unit aim."],"question":"Which statement is a common mistake when practising review?","type":"multiple_choice"},{"correct_index":2,"explanation":"Understanding is shown by new evidence and named food, not by copying the model.","options":["Choose randomly because any option could be right.","Treat a skipped permission or safety step as if it did not matter.","Apply the idea with new evidence and name the food used.","Repeat the worked example wording with no new evidence."],"question":"A learner is practising review. Which approach best shows understanding?","type":"multiple_choice"},{"correct_index":0,"explanation":"Fair compare; wash hands / adult for heat. uses safe, healthy, respectful choices appropriately for this lesson.","options":["Fair compare; wash hands / adult for heat.","Review that shames food choices fails the unit aim.","Ignore the safety rule because the first idea looked exciting.","Copy the example and call that independent work."],"question":"Which response best shows careful thinking about review?","type":"multiple_choice"},{"correct_index":0,"explanation":"Strong answers name specific evidence and what it shows.","options":["Name a specific source, cue or example and say what it shows about review.","Make a bigger claim without naming any source or cue.","Copy a classmate’s sentence with no local detail.","Review that shames food choices fails the unit aim."],"question":"Which habit strengthens evidence about food?","type":"multiple_choice"},{"correct_index":2,"explanation":"The stronger choice matches the taught idea with concrete detail.","options":["Treat a skipped permission or safety step as if it did not matter.","Ignore the safety rule because the first idea looked exciting.","Review path: groups → detective → labels → lunchbox → ad tricks → safety.","Review that shames food choices fails the unit aim."],"question":"Using this lesson idea — Unit review connects food groups, labels, lunchboxes, advertising and food safety with respectful language. — which choice is best?","type":"multiple_choice"},{"correct_index":1,"explanation":"Respect and accuracy mean checking evidence and honouring limits/protocols.","options":["Treat every online claim as equally reliable.","Check facts/cues, acknowledge limits, and avoid inventing details.","Invent missing details to make the answer sound complete.","Ignore safety or cultural protocols to finish faster."],"question":"Which action shows respect and accuracy together?","type":"multiple_choice"},{"correct_index":2,"explanation":"Independence requires a new example that still uses the skill.","options":["Copy the example and call that independent work.","Review that shames food choices fails the unit aim.","Fourteen-item food review + showcase: label compare and kind lunchbox plan. Two goals.","Retype the worked example with no new example."],"question":"Which task best shows independent use of review?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Require independently produced work with a specific supporting detail.","question":"Produce a fresh example demonstrating review on new material (not the worked model). Explain the particular words, sources or choices that make it work.","sample_answer":"Original response on new material: Fair compare; wash hands / adult for heat. Reasoning: I used review by attending to food rather than copying the worked model.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Require misconception + correction + purpose-linked reason.","question":"Name one likely error with review, correct it, and explain why the correction helps a reader or audience.","sample_answer":"Common error: Review that shames food choices fails the unit aim. Correction: Fair compare; wash hands / adult for heat. Why: the correction restores accurate use of review.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested. Share only what you feel comfortable sharing.","review_status":"unreviewed","seed_key":"s2-pdhpe-y4-w15-l2","sort_activity":null,"source_note":"Proposed Stage 2 NESA PDHPE alignment using catalogue outcome codes (PH2-*); content-point mapping remains pending human review. Physical activities are optional, adult-supervised and adaptable; no child is required to share personal details.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise review.","Read the mission before you start moving or deciding.","Keep your own safety and everyone''s inclusion in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your reasons with the feedback.","Adjust anything that does not keep everyone safe and included."],"learn":["Study how the first demonstration is built.","Point to the cue or rule that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore safety, consent or inclusion.","Prefer a reasoned, respectful choice over one that merely looks fun."],"submit":["Confirm that your reasons and reflection are both present.","Proofread names, steps and safety words.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked example.","Name one exact cue, rule or choice before you decide.","Think through the small prompt before opening the comparison."],"teach1":["Return to the example and list the key cues.","Say what each cue does for safety, health or friendship.","A final label alone is weaker than a stated reason."],"teach2":["Compare an unsafe or unkind choice with a better one.","Change the choice or strategy, not only the words.","Name the mistake you are repairing."],"teach3":["Choose a fresh place, game or situation that still uses the same skill.","Write one reason in your own words.","Do not retype the worked example as your answer."],"write":["Follow every part of the independent instructions.","Include original reasons and a short reflection.","Save work that shows the skill in a new situation."]},"subject":"Healthy, Safe and Active Lifestyles","success_criteria":["I can use review with a specific example from this lesson.","I can identify food and explain why it matters.","I can practise label independently on a new prompt.","I can notice choice needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":0,"explanation":"Unit review connects food groups, labels, lunchboxes, advertising and food safety with respectful language. Supported choices follow the actual cues, rules and purpose of the task.","options":["Unit review connects food groups, labels, lunchboxes, advertising and food safety with respectful language.","A choice unrelated to safety, health or respect.","An answer copied without understanding.","A guess with no reason."],"question":"Which choice best shows accurate use of this idea about review?","type":"multiple_choice"},"example":"WORKED MODEL\nReview path: groups → detective → labels → lunchbox → ad tricks → safety.\n\nTRY FIRST\nMini: per 100 g why; one safety rule.\n\nFEEDBACK\nFair compare; wash hands / adult for heat.","explain":"Unit review connects food groups, labels, lunchboxes, advertising and food safety with respectful language.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Review that shames food choices fails the unit aim. Change the choice or strategy, not just the wording.","title":"Understand and demonstrate","visual":[{"alt":"Food unit review.","caption":"No shaming.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Review path</text><text x=\"28\" y=\"78\">groups→labels→safety</text><text x=\"358\" y=\"42\">Respect</text><text x=\"358\" y=\"78\">language</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which cue or rule matters most.","who":"pip"},{"text":"Name the cues, rules or choices that keep everyone safe and included before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this example: Review path: groups → detective → labels → lunchbox → ad tricks → safety. Then write your own reasons.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which cue or rule matters most.\nJuno: Name the cues, rules or choices that keep everyone safe and included before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this example: Review path: groups → detective → labels → lunchbox → ad tricks → safety. Then write your own reasons."}}]},{"check":{"correct_index":3,"explanation":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others. Supported choices follow the actual cues, rules and purpose of the task.","options":["A choice unrelated to safety, health or respect.","An answer copied without understanding.","A guess with no reason.","Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others."],"question":"Which choice best shows accurate use of this idea about review?","type":"multiple_choice"},"example":"WORKED MODEL\nReview path: groups → detective → labels → lunchbox → ad tricks → safety. Look at each cue, rule or choice that carries the idea.\n\nTRY FIRST\nList the key cues, rules or choices from the example and say what each one does for safety, health or relationships.\n\nFEEDBACK\nThe most useful reasoning names the cue, rule or strategy and the reason it helps, not only a label such as \"good\".","explain":"Make the PDHPE idea visible: name the body cue, safety rule or wellbeing strategy you used and say why it helps you or others.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Writing only a final label without a reason does not show PDHPE thinking. Change the choice or strategy, not just the wording.","title":"Show the reasoning","visual":[{"alt":"Food review.","caption":"Two goals.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Fourteen items</text><text x=\"28\" y=\"78\">showcase</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">judge lunches</text></g></svg>"}]},{"check":{"correct_index":2,"explanation":"Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice. Supported choices follow the actual cues, rules and purpose of the task.","options":["An answer copied without understanding.","A guess with no reason.","Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice.","A choice unrelated to safety, health or respect."],"question":"Which choice best shows accurate use of this idea about review?","type":"multiple_choice"},"example":"WORKED MODEL\nReview that shames food choices fails the unit aim. Here is a more helpful example: Review path: groups → detective → labels → lunchbox → ad tricks → safety.\n\nTRY FIRST\nDescribe why the warned-against choice does not work, then write a safer, kinder or healthier choice with a reason.\n\nFEEDBACK\nFair compare; wash hands / adult for heat.","explain":"Use an intentionally unsafe or unhelpful choice as a comparison. Name the specific PDHPE error, then show the safer or more respectful choice.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Changing the wording without changing the choice does not fix the error. Review that shames food choices fails the unit aim. Change the choice or strategy, not just the wording.","title":"Test a misconception"},{"check":{"correct_index":1,"explanation":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion. Supported choices follow the actual cues, rules and purpose of the task.","options":["A guess with no reason.","Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion.","A choice unrelated to safety, health or respect.","An answer copied without understanding."],"question":"Which choice best shows accurate use of this idea about review?","type":"multiple_choice"},"example":"WORKED MODEL\nUnit review connects food groups, labels, lunchboxes, advertising and food safety with respectful language. Now choose a different situation to show you can transfer the idea.\n\nTRY FIRST\nDescribe or practise one fresh situation that uses the same skill and write a short reason for your choice.\n\nFEEDBACK\nThe new situation should use the same PDHPE idea as the example, but happen in a different place or with different people.","explain":"Use the same PDHPE idea in a new place, game or situation, not a copy of the example. Review safety, fairness and inclusion.\n\nWHY IT MATTERS\nThis helps the learner make safe, healthy and respectful choices using clear cues and reasons, rather than guessing or copying others. Every choice keeps bodies safe and includes everyone.\n\nHOW TO WORK\nRead the worked example and name the cues, rules or choices that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. For any movement, use a clear space, ask an adult to be nearby, move at your own comfortable level and stop if anything hurts or feels unsafe. You may always choose a gentler version or only describe the movement. One deliberate, reasoned change is more useful than a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to a new situation. Change the choice or strategy, not just the wording.","title":"Transfer to a new situation"}],"title":"Year 4, Week 15, Lesson 2: Unit review and showcase","unit_number":3,"unit_title":"Nutrition and healthy choices","week":15,"week_in_unit":5,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nReview path: groups → detective → labels → lunchbox → ad tricks → safety.\n\nWrite what makes this example safe, healthy or respectful, naming the cues, rules or choices used.","worked_visuals":[{"alt":"Food unit review.","caption":"No shaming.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Review path</text><text x=\"28\" y=\"78\">groups→labels→safety</text><text x=\"358\" y=\"42\">Respect</text><text x=\"358\" y=\"78\">language</text></g></svg>"},{"alt":"Food review.","caption":"Two goals.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Fourteen items</text><text x=\"28\" y=\"78\">showcase</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">judge lunches</text></g></svg>"}],"year_level":"Year 4"}') WHERE seed_key='s2-pdhpe-y4-w15-l2' AND family_id IS NULL;
